/**
 * The local fallback decoder: the engine's vocabulary (about 23k words with unigram frequencies,
 * `lexicon.json`, generated by `scripts/build-lexicon.mjs`) and three tables read off the engine's
 * ARPA 4-gram by the scripts beside it: the next words after one word (`bigrams.json`), after two
 * words (`trigrams.json`), and which function words may introduce each content word (`echo.json`).
 * It answers synchronously, so the screen always has a word even when the engine is unreachable or
 * slow, and it answers in the engine's own shape, including `complete: true` pages (exact-length
 * words only) for the Other words chooser and `display` for a name the partner wrote with a capital.
 *
 * Ranking (round 4) follows the engine's own recipe (`v1/engine/cache.py`, `predictor.py`) as far
 * as n-gram tables allow:
 *
 *  - The language model: p(word | the two words before it) from the trigram table, else
 *    p(word | the word before) from the bigram table or, for a content word after a function word,
 *    the echo table, else the word's unigram frequency scaled down.
 *  - The pointer cache: every word of the conversation, weighted by turn (the partner's 1.0, the
 *    person's 0.5, decaying 0.7 per turn of age), capped at three mentions, names doubled, and damped
 *    for frequent words (a word more common than 2e-4 keeps 2e-4 / its frequency), so "cold" counts
 *    and "you" does not. The cache is mixed in: p = (1 − λ) p_lm + λ p_cache, with λ larger while
 *    typing than for the next word (CACHE_MIX_TYPING, CACHE_MIX_NEXT).
 *  - Tiers: a word the tables know as a continuation comes first (tier 0); so does a partner's
 *    content word (cache share ≥ ECHO_FLOOR), at every rank, while typing, and, for the next word,
 *    when the echo table finds it ECHO_PMI times likelier after the word before it than in general
 *    ("I am not cold": p(cold | not) is nine times p(cold); "not coffee" is under four; "I cold" has no entry).
 *    Everything else backs off to tier 1. Within a tier, p decides.
 *  - Endings: the next word is nudged towards words a sentence can end on (END_BONUS), so a tie in
 *    the tables resolves to "I am not sure" rather than "I am not to".
 *  - Repeats: the word just accepted is never the next word, and a word already in the message keeps
 *    a tenth of its mass, so the chain never loops ("to for to for", "tonight and i am tonight").
 *    While typing nothing is demoted: typing the code of a word again is deliberate ("no no").
 *  - A partner's word the lexicon does not know (a name) is a candidate too, with its own code and
 *    its written form as `display`, as the engine offers words the conversation introduced.
 *
 * When nothing matches the typed groups it still names a word the person can accept: the best
 * word one digit off (a gaze slip, the engine's own `corrected` idea), else the best word for the
 * longest prefix that matches. So Q1 is never empty, however many groups were typed.
 */
import { signatureOf } from '../../shared/decoder.ts';
import LEXICON from './lexicon.json' with { type: 'json' };
import BIGRAMS from './bigrams.json' with { type: 'json' };
import TRIGRAMS from './trigrams.json' with { type: 'json' };
import ECHO from './echo.json' with { type: 'json' };
import ENDS from './ends.json' with { type: 'json' };
import type { Fallback, PredictRequest, Prediction, PredictedWord } from './prediction.ts';

type Row = [string, number];
type Table = Record<string, [string, number][]>;
const rows = LEXICON as Row[];
const index = new Map<string, number>(rows.map(([word], i) => [word, i]));

/** Group codes ("34") and linear frequencies, in the lexicon's order (best first). */
const codes: string[] = rows.map(([word]) => signatureOf(word).map((g) => g.slice(1)).join(''));
const freq: number[] = rows.map(([, log]) => 10 ** log);
const freqMass = freq.reduce((a, b) => a + b, 0);
/** Unigram probability, as the back-off. */
const unigram: number[] = freq.map((f) => f / freqMass);

function tableOf(raw: Table): Map<string, Map<number, number>> {
  return new Map(Object.entries(raw).map(([key, list]) => [key, new Map(list.filter(([w]) => index.has(w)).map(([w, log]) => [index.get(w)!, 10 ** log]))]));
}
/** prev → (next → p), from the engine's 4-gram's 2-gram section. `<s>` is the sentence start. */
const bigram = tableOf(BIGRAMS as unknown as Table);
/** "prev2 prev" → (next → p), from the 3-gram section. */
const trigram = tableOf(TRIGRAMS as unknown as Table);
/** The echo table: for a content word, p(word | function word) for the function words the model has seen before it. */
const echoRaw = ECHO as unknown as { _function: string[] } & Record<string, string | string[]>;
const functionBit = new Map<string, number>((echoRaw._function as string[]).map((w, i) => [w, i]));
const echoPairs = new Map<string, Map<number, number> | null>();
/** The model's p(word | prev) when prev is a function word the model has seen before `word`, else 0. */
function echoP(word: string, prev: string): number {
  const bit = functionBit.get(prev);
  if (bit === undefined) return 0;
  let pairs = echoPairs.get(word);
  if (pairs === undefined) {
    const raw = echoRaw[word];
    if (typeof raw === 'string') {
      const bytes = Uint8Array.from(atob(raw), (c) => c.charCodeAt(0));
      pairs = new Map();
      for (let k = 0; k + 1 < bytes.length; k += 2) pairs.set(bytes[k], 10 ** (-bytes[k + 1] / 32));
    } else pairs = null;
    echoPairs.set(word, pairs);
  }
  return pairs?.get(bit) ?? 0;
}

/**
 * The cache's share of the mixture (a cache language model's interpolation weight). While typing the
 * partner's words should surface early ("te" → tea), so the cache weighs more; for the next word it
 * weighs little, so a partner's word is offered unprompted only when the model half expects it there
 * ("for dinner") or when one content word owns the whole turn ("Are you cold?" → "I am cold").
 */
const CACHE_MIX_TYPING = 0.12;
const CACHE_MIX_NEXT = 0.04;
const DECAY = 0.7;
const PARTNER = 1.0;
const USER = 0.5;
const IN_MESSAGE = 0.15;
const IDF_FLOOR = 2e-4;
const NAME_BOOST = 2;
/** The share of the cache from which a word counts as content worth echoing ("you" never reaches it). */
const ECHO_FLOOR = 0.02;
/** An echoed word follows the word before it only where the model finds it this many times likelier there than in general. */
const ECHO_PMI = 5;
/**
 * The next word is nudged towards words a sentence can end on: × (1 + END_BONUS × p(</s> | word)),
 * read off the model (`ends.json`). Replies are short, and the model's three-word contexts often
 * tie ("I am not" → to, a, sure, so within 0.04 log); this breaks such ties towards "sure".
 */
const END_BONUS = 1;
const ends = new Map<string, number>(Object.entries(ENDS as unknown as Record<string, number>).map(([w, log]) => [w, 10 ** log]));
/** A word with no n-gram counts as this fraction of its unigram probability (the back-off). */
const BACKOFF = 0.02;
/** A bigram continuation when a trigram context exists but does not list the word. */
const TRI_BACKOFF = 0.4;
/** A word already in the message keeps this share of its mass as the next word (the engine discounts the last three; without its rescorer the fallback discounts them all, so a chain never loops). */
const REPEAT_DISCOUNT = 0.1;
/** Beyond this many groups a slip search (3 × length scans) is not worth it; the prefix rule holds. */
const CORRECT_UP_TO = 16;
const MEMO_SIZE = 16;

const TOKEN = /[a-z][a-z']*/g;
const RAW = /[A-Za-z][A-Za-z']*/g;
const wordsOf = (text: string): string[] => text.replace(/’/g, "'").toLowerCase().match(TOKEN) ?? [];

/** Capitalised, uncommon tokens that do not start a sentence: a name, with its written form (the engine's `name_like`). */
function namesIn(text: string): Map<string, string> {
  const out = new Map<string, string>();
  const t = text.replace(/’/g, "'");
  for (const m of t.matchAll(RAW)) {
    const tok = m[0];
    if (!(tok[0] >= 'A' && tok[0] <= 'Z' && tok.slice(1) === tok.slice(1).toLowerCase() && tok.length > 1)) continue;
    const before = t.slice(0, m.index).trimEnd();
    if (!before || /[.!?]$/.test(before)) continue;
    const w = tok.toLowerCase();
    const i = index.get(w);
    if (i === undefined || unigram[i] < 5e-5) out.set(w, tok);
  }
  return out;
}

type Cache = { share: Map<string, number>; display: Map<string, string> };

/** The pointer cache over the conversation: each word's share of it (summing to 1), and names' written forms. */
function cacheOf(req: PredictRequest): Cache {
  const weights = new Map<string, number>();
  const display = new Map<string, string>();
  const history = req.history;
  for (let age = 0; age < history.length; age++) {
    const [role, text] = history[history.length - 1 - age];
    const base = (role === 'partner' ? PARTNER : USER) * DECAY ** age;
    if (base < 1e-3) break;
    const names = namesIn(text);
    for (const [w, form] of names) if (!display.has(w)) display.set(w, form);
    const seen = new Map<string, number>();
    for (const w of wordsOf(text)) {
      seen.set(w, (seen.get(w) ?? 0) + 1);
      if (w.endsWith("'s") && w.length > 3) seen.set(w.slice(0, -2), (seen.get(w.slice(0, -2)) ?? 0) + 1);
    }
    for (const [w, c] of seen) weights.set(w, (weights.get(w) ?? 0) + base * Math.min(c, 3) * (names.has(w) || names.has(`${w}'s`) ? NAME_BOOST : 1));
  }
  for (const w of new Set(req.message.map((m) => m.toLowerCase()))) weights.set(w, (weights.get(w) ?? 0) + IN_MESSAGE);
  let total = 0;
  for (const [w, weight] of weights) {
    const i = index.get(w);
    const f = i === undefined ? 0 : unigram[i];
    const damped = f > IDF_FLOOR ? weight * (IDF_FLOOR / f) : weight;
    weights.set(w, damped);
    total += damped;
  }
  const share = new Map<string, number>();
  if (total > 0) for (const [w, weight] of weights) share.set(w, weight / total);
  return { share, display };
}

/** The best-ranked word whose code starts with `code` (first in the lexicon's frequency order). */
function bestFor(code: string): string | null {
  for (let i = 0; i < rows.length; i++) if (codes[i].startsWith(code)) return rows[i][0];
  return null;
}

/** A word for groups that match nothing: one digit off, else the longest matching prefix. */
export function fallbackFor(groups: string): Fallback | undefined {
  if (!groups) return undefined;
  if (groups.length <= CORRECT_UP_TO) {
    let best: { word: string; f: number } | null = null;
    for (let i = 0; i < groups.length; i++) {
      for (const alt of '1234') {
        if (alt === groups[i]) continue;
        const code = groups.slice(0, i) + alt + groups.slice(i + 1);
        for (let j = 0; j < rows.length; j++) {
          if (!codes[j].startsWith(code)) continue;
          if (!best || freq[j] > best.f) best = { word: rows[j][0], f: freq[j] };
          break; // rows are best first: the first match is this code's best
        }
      }
    }
    if (best) return { word: best.word, kind: 'corrected' };
  }
  for (let len = groups.length - 1; len >= 1; len--) {
    const word = bestFor(groups.slice(0, len));
    if (word) return { word, kind: 'prefix' };
  }
  return undefined;
}

/** The next words the tables know after `prev` (and `prev2` before it), best first: for tests. */
export function nextWordsOf(prev: string | null, prev2: string | null = null): string[] {
  const out: string[] = [];
  const add = (list?: Map<number, number>) => { if (list) for (const i of [...list.entries()].sort((a, b) => b[1] - a[1]).map(([i]) => i)) if (!out.includes(rows[i][0])) out.push(rows[i][0]); };
  if (prev !== null) add(trigram.get(`${prev2 ?? '<s>'} ${prev}`));
  add(bigram.get(prev ?? '<s>'));
  return out;
}

/** Whether the echo rule lets the partner's `word` follow `prev` as the next word (for tests). */
export function canFollow(word: string, prev: string): boolean {
  const i = index.get(word);
  return i !== undefined && echoP(word, prev) >= ECHO_PMI * unigram[i];
}

const memo = new Map<string, Prediction>();

export function predictLocal(req: PredictRequest, pageSize = 8): Prediction {
  const limit = req.limit ?? pageSize;
  const key = JSON.stringify([req.history, req.message, req.groups, req.offset, req.complete ?? false, limit]);
  const hit = memo.get(key);
  if (hit) return hit;
  const groups = req.groups;
  const message = req.message.map((w) => w.toLowerCase());
  const last = message.length ? message[message.length - 1] : null;
  const prev2 = message.length > 1 ? message[message.length - 2] : null;
  const cache = cacheOf(req);
  const after2 = last !== null ? trigram.get(`${prev2 ?? '<s>'} ${last}`) : undefined;
  const after = bigram.get(last ?? '<s>');
  const recent = new Set(groups ? [] : message);
  /** The tables' p(word | before): the trigram, else the bigram, else the echo table for a content word, else the unigram back-off. */
  const lm = (i: number): number => {
    const tri = after2?.get(i);
    if (tri !== undefined) return tri;
    const bi = after?.get(i);
    if (bi !== undefined) return bi * (after2 ? TRI_BACKOFF : 1);
    const echo = last !== null ? echoP(rows[i][0], last) : 0;
    return echo > 0 ? echo * (after2 ? TRI_BACKOFF : 1) : unigram[i] * BACKOFF;
  };
  const known = (i: number): boolean => Boolean(after2?.has(i) || after?.has(i));
  /** Mixed probability of a word, and its tier (0: a continuation the tables or the echo rule stand behind). */
  const mix = groups ? CACHE_MIX_TYPING : CACHE_MIX_NEXT;
  const score = (i: number, p: number): [number, number] => {
    const word = rows[i][0];
    const share = cache.share.get(word) ?? 0;
    let mixed = (1 - mix) * p + mix * share;
    if (!groups) mixed *= 1 + END_BONUS * (ends.get(word) ?? 0);
    if (recent.has(word)) mixed *= REPEAT_DISCOUNT;
    // A partner's content word is echoed at every rank while typing; as the next word only where the
    // model finds it clearly likelier after the word before it than in general ("am cold", not "am coffee").
    const echoed = share >= ECHO_FLOOR && (groups ? true : last !== null && echoP(word, last) >= ECHO_PMI * unigram[i]);
    return [mixed, known(i) || echoed ? 0 : 1];
  };
  type Scored = { word: string; code: string; p: number; tier: number; display?: string };
  const scored: Scored[] = [];
  let mass = 0;
  let longer = 0;
  const take = (entry: Scored) => {
    if (req.complete && entry.code.length !== groups.length) return;
    mass += entry.p;
    if (entry.code.length > groups.length) longer += entry.p;
    scored.push(entry);
  };
  for (let i = 0; i < rows.length; i++) {
    if (!codes[i].startsWith(groups)) continue;
    // The word just accepted is never the next word.
    if (!groups && last !== null && rows[i][0] === last) continue;
    const [p, tier] = score(i, lm(i));
    take({ word: rows[i][0], code: codes[i], p, tier });
  }
  // Words the conversation introduced that the lexicon lacks (a name): offered with their own code.
  for (const [word, share] of cache.share) {
    if (index.has(word) || !/^[a-z][a-z']*$/.test(word)) continue;
    const code = signatureOf(word).map((g) => g.slice(1)).join('');
    if (!code.startsWith(groups) || (!groups && word === last)) continue;
    const p = mix * share * (recent.has(word) ? REPEAT_DISCOUNT : 1);
    const entry: Scored = { word, code, p, tier: groups && share >= ECHO_FLOOR ? 0 : 1 };
    const display = cache.display.get(word);
    if (display) entry.display = display;
    take(entry);
  }
  // Tier first, then p; ties keep the lexicon's frequency order (the sort is stable).
  scored.sort((a, b) => a.tier - b.tier || b.p - a.p);
  const total = scored.length;
  const offset = total ? req.offset % total : 0;
  const words: PredictedWord[] = scored.slice(offset, offset + limit).map((s) => {
    const w: PredictedWord = { word: s.word, p: mass ? s.p / mass : 0, complete: s.code.length === groups.length };
    if (s.display) w.display = s.display;
    return w;
  });
  const value: Prediction = { words, total, longer: mass ? longer / mass : 0, offset, source: 'local' };
  if (total === 0 && groups && !req.complete) {
    const fallback = fallbackFor(groups);
    if (fallback) value.fallback = fallback;
  }
  memo.delete(key);
  memo.set(key, value);
  if (memo.size > MEMO_SIZE) memo.delete(memo.keys().next().value!);
  return value;
}
